import { describe, expect, it } from "vitest";
import {
  ConversationEventType,
  UtteranceType,
  type ConversationEvent,
  type Utterance,
} from "../../types";
import { groupEventsByToolCall } from "./groupEventsByToolCall";

function conversationEvent(
  id: string,
  type: ConversationEventType,
  overrides: Partial<ConversationEvent> = {},
): ConversationEvent {
  return {
    id,
    conversationEventType: type,
    name: "",
    actionText: "",
    flowId: "",
    stepId: "",
    slotValue: null,
    timestamp: "2020-01-01T00:00:00.000Z",
    originalTimestamp: 0,
    metadata: { parseData: {} },
    __typename: "ConversationEvent",
    ...overrides,
  };
}

// A tool-run marker stamped with the dispatching LLM call id (the join key).
function toolCall(
  id: string,
  toolName: string,
  toolCallId?: string,
  type: ConversationEventType = ConversationEventType.McpToolExecuted,
  toolSource?: "local" | "mcp",
): ConversationEvent {
  return conversationEvent(id, type, {
    metadata: {
      parseData: {},
      tool_name: toolName,
      ...(toolCallId !== undefined ? { tool_call_id: toolCallId } : {}),
      ...(toolSource !== undefined ? { tool_source: toolSource } : {}),
    },
  });
}

// A memory write stamped with the id of the call that produced it.
function toolWrite(
  id: string,
  toolCallId: string,
  type: ConversationEventType = ConversationEventType.Slot,
): ConversationEvent {
  return conversationEvent(id, type, {
    name: "x",
    metadata: {
      parseData: {},
      mantle_write_provenance: { tool: null, position: 1, tool_call_id: toolCallId },
    },
  });
}

function botMessage(id: string): Utterance {
  return {
    __typename: "Utterance",
    id,
    metadata: { parseData: {} },
    rephrase: false,
    rephrasePrompt: null,
    text: "Hello",
    timestamp: "2020-01-01T00:00:00.000Z",
    tokens: [],
    type: UtteranceType.Bot,
    originalTimestamp: 0,
  };
}

describe("groupEventsByToolCall", () => {
  it("collects a call's id-stamped writes under the call", () => {
    const items = groupEventsByToolCall([
      toolCall("call", "check_replacement_eligibility", "c1"),
      toolWrite("w1", "c1", ConversationEventType.MemorySet),
      toolWrite("w2", "c1", ConversationEventType.MemoryCleared),
    ]);
    expect(items).toHaveLength(1);
    expect(items[0]).toMatchObject({ kind: "tool-group" });
    const group = items[0] as { call: ConversationEvent; children: ConversationEvent[] };
    expect(group.call.id).toBe("call");
    expect(group.children.map((child) => child.id)).toEqual(["w1", "w2"]);
  });

  it("joins writes by id list-wide, across a hook marker and a message", () => {
    // Writes are appended before their marker on the tracker; a no-id
    // post-write-hook marker and a bot message sit between the write and its
    // call, yet the id join nests the write under its call regardless.
    const items = groupEventsByToolCall([
      toolWrite("early", "c1"),
      toolCall("hook", "post_write_hook"),
      botMessage("msg"),
      toolCall("call", "set_fields", "c1"),
    ]);
    expect(items.map((item) => item.kind)).toEqual(["tool-group", "event", "tool-group"]);
    // The no-id hook marker owns nothing; the message stays at the top level.
    expect((items[0] as { children: ConversationEvent[] }).children).toEqual([]);
    const callGroup = items[2] as { call: ConversationEvent; children: ConversationEvent[] };
    expect(callGroup.call.id).toBe("call");
    expect(callGroup.children.map((child) => child.id)).toEqual(["early"]);
  });

  it("joins only writes whose id matches the call", () => {
    const items = groupEventsByToolCall([
      toolCall("callX", "set_fields", "X"),
      toolWrite("wX", "X"),
      toolCall("callY", "set_fields", "Y"),
      toolWrite("wY", "Y"),
    ]);
    expect(items.map((item) => item.kind)).toEqual(["tool-group", "tool-group"]);
    const groupX = items[0] as { call: ConversationEvent; children: ConversationEvent[] };
    const groupY = items[1] as { call: ConversationEvent; children: ConversationEvent[] };
    expect(groupX.call.id).toBe("callX");
    expect(groupX.children.map((child) => child.id)).toEqual(["wX"]);
    expect(groupY.call.id).toBe("callY");
    expect(groupY.children.map((child) => child.id)).toEqual(["wY"]);
  });

  it("gives a tool row without a call id no children", () => {
    // Engine-invoked hooks / execute steps carry no tool_call_id, so there is
    // nothing to attribute to them.
    const items = groupEventsByToolCall([toolCall("call", "run_hook"), toolWrite("w", "c1")]);
    expect(items.map((item) => item.kind)).toEqual(["tool-group", "event"]);
    expect((items[0] as { children: ConversationEvent[] }).children).toEqual([]);
    expect((items[1] as { event: ConversationEvent }).event.id).toBe("w");
  });

  it("does not attach id-stamped writes to an LLM call row", () => {
    const items = groupEventsByToolCall([
      conversationEvent("llm", ConversationEventType.LlmCallRecorded),
      toolWrite("w", "c1"),
    ]);
    expect(items.map((item) => item.kind)).toEqual(["llm-group", "event"]);
    expect((items[0] as { children: ConversationEvent[] }).children).toEqual([]);
  });

  it("keeps unstamped writes at the top level", () => {
    const items = groupEventsByToolCall([
      toolCall("call", "list_cards", "c1"),
      conversationEvent("plain", ConversationEventType.MemorySet, { name: "y" }),
    ]);
    expect(items.map((item) => item.kind)).toEqual(["tool-group", "event"]);
    expect((items[0] as { children: ConversationEvent[] }).children).toEqual([]);
  });

  it.each([ConversationEventType.Slot, ConversationEventType.MemorySet])(
    "groups a %s discovered-facts write under the producing LLM call",
    (type) => {
      const items = groupEventsByToolCall([
        conversationEvent("discovery", ConversationEventType.LlmCallRecorded),
        conversationEvent("facts", type, {
          name: "system.__discovered__",
        }),
        conversationEvent("unrelated", type, { name: "x" }),
      ]);
      expect(items.map((item) => item.kind)).toEqual(["llm-group", "event"]);
      expect((items[0] as { children: ConversationEvent[] }).children.map((c) => c.id)).toEqual([
        "facts",
      ]);
    },
  );

  it("a message breaks the discovered-facts adjacency join", () => {
    const items = groupEventsByToolCall([
      conversationEvent("discovery", ConversationEventType.LlmCallRecorded),
      botMessage("msg"),
      conversationEvent("facts", ConversationEventType.Slot, { name: "system.__discovered__" }),
    ]);
    expect(items.map((item) => item.kind)).toEqual(["llm-group", "event", "event"]);
    expect((items[0] as { children: ConversationEvent[] }).children).toEqual([]);
  });

  it.each([ConversationEventType.McpToolExecuted, ConversationEventType.ToolExecuted])(
    "hides local activate rows on %s (narrated as skill activations)",
    (type) => {
      const items = groupEventsByToolCall([
        toolCall("activate", "activate", undefined, type, "local"),
        toolCall("call", "check_replacement_eligibility", "c1", type),
        toolWrite("w1", "c1"),
      ]);
      expect(items).toHaveLength(1);
      const group = items[0] as { call: ConversationEvent; children: ConversationEvent[] };
      expect(group.call.id).toBe("call");
      expect(group.children.map((child) => child.id)).toEqual(["w1"]);
    },
  );

  it.each([ConversationEventType.McpToolExecuted, ConversationEventType.ToolExecuted])(
    "keeps MCP activate rows on %s and groups their writes",
    (type) => {
      const items = groupEventsByToolCall([
        toolCall("activate", "activate", "a1", type, "mcp"),
        toolWrite("w1", "a1"),
        toolCall("call", "lock_card", "c1", type),
      ]);
      expect(items.map((item) => item.kind)).toEqual(["tool-group", "tool-group"]);
      const activateGroup = items[0] as { call: ConversationEvent; children: ConversationEvent[] };
      expect(activateGroup.call.id).toBe("activate");
      expect(activateGroup.children.map((child) => child.id)).toEqual(["w1"]);
      expect((items[1] as { call: ConversationEvent }).call.id).toBe("call");
    },
  );

  it("groups mixed historical and current tool events", () => {
    const items = groupEventsByToolCall([
      toolCall("legacy", "list_cards", "c1", ConversationEventType.McpToolExecuted),
      toolWrite("w1", "c1"),
      toolCall("current", "lock_card", "c2", ConversationEventType.ToolExecuted),
      toolWrite("w2", "c2"),
    ]);
    expect(items.map((item) => item.kind)).toEqual(["tool-group", "tool-group"]);
    expect((items[0] as { call: ConversationEvent }).call.id).toBe("legacy");
    expect((items[1] as { call: ConversationEvent }).call.id).toBe("current");
    expect(
      (items[0] as { children: ConversationEvent[] }).children.map((child) => child.id),
    ).toEqual(["w1"]);
    expect(
      (items[1] as { children: ConversationEvent[] }).children.map((child) => child.id),
    ).toEqual(["w2"]);
  });

  it("shows the compatibility MCP event of a dual-emitted local activate", () => {
    const items = groupEventsByToolCall([
      toolCall("mcp-activate", "activate", "a1", ConversationEventType.McpToolExecuted, "mcp"),
      toolCall(
        "local-activate",
        "activate",
        undefined,
        ConversationEventType.ToolExecuted,
        "local",
      ),
      toolCall(
        "call",
        "check_replacement_eligibility",
        "c1",
        ConversationEventType.ToolExecuted,
        "local",
      ),
      toolWrite("w1", "c1"),
    ]);
    expect(items).toHaveLength(2);
    expect((items[0] as { call: ConversationEvent }).call.id).toBe("mcp-activate");
    const toolGroup = items[1] as { call: ConversationEvent; children: ConversationEvent[] };
    expect(toolGroup.call.id).toBe("call");
    expect(toolGroup.children.map((child) => child.id)).toEqual(["w1"]);
  });

  it("a message closes nothing but stays at the top level", () => {
    const items = groupEventsByToolCall([
      toolCall("call", "lock_card", "c1"),
      toolWrite("w1", "c1"),
      botMessage("msg"),
    ]);
    expect(items.map((item) => item.kind)).toEqual(["tool-group", "event"]);
    expect((items[0] as { children: ConversationEvent[] }).children.map((c) => c.id)).toEqual([
      "w1",
    ]);
    expect((items[1] as { event: Utterance }).event.id).toBe("msg");
  });

  it("folds a local set_fields row into the predicting LLM call's caret", () => {
    // The writes precede their marker on the tracker; the LLM row precedes both.
    const items = groupEventsByToolCall([
      conversationEvent("llm", ConversationEventType.LlmCallRecorded),
      toolWrite("w1", "c1", ConversationEventType.MemorySet),
      toolCall("set", "set_fields", "c1", ConversationEventType.ToolExecuted, "local"),
    ]);
    expect(items.map((item) => item.kind)).toEqual(["llm-group"]);
    const group = items[0] as { call: ConversationEvent; children: ConversationEvent[] };
    expect(group.call.id).toBe("llm");
    expect(group.children.map((child) => child.id)).toEqual(["w1"]);
  });

  it("keeps an MCP tool named set_fields as its own row", () => {
    const items = groupEventsByToolCall([
      conversationEvent("llm", ConversationEventType.LlmCallRecorded),
      toolWrite("w1", "c1", ConversationEventType.MemorySet),
      toolCall("set", "set_fields", "c1", ConversationEventType.McpToolExecuted, "mcp"),
    ]);
    expect(items.map((item) => item.kind)).toEqual(["llm-group", "tool-group"]);
    const toolGroup = items[1] as { call: ConversationEvent; children: ConversationEvent[] };
    expect(toolGroup.call.id).toBe("set");
    expect(toolGroup.children.map((child) => child.id)).toEqual(["w1"]);
  });

  it("keeps a local set_fields row when no LLM call precedes it", () => {
    const items = groupEventsByToolCall([
      toolWrite("w1", "c1", ConversationEventType.MemorySet),
      toolCall("set", "set_fields", "c1", ConversationEventType.ToolExecuted, "local"),
    ]);
    expect(items.map((item) => item.kind)).toEqual(["tool-group"]);
    expect((items[0] as { children: ConversationEvent[] }).children.map((c) => c.id)).toEqual([
      "w1",
    ]);
  });

  it("does not count a hidden system write toward a tool call's caret", () => {
    // A caret must not appear when its only write renders as null (see
    // isHiddenSystemMemoryEntry) — it would expand to nothing.
    const items = groupEventsByToolCall([
      toolCall("call", "lock_card", "c1", ConversationEventType.ToolExecuted, "local"),
      conversationEvent("sys", ConversationEventType.MemorySet, {
        name: "system.internal_flag",
        metadata: {
          parseData: {},
          mantle_write_provenance: { tool: null, position: 1, tool_call_id: "c1" },
        },
      }),
    ]);
    expect(items.map((item) => item.kind)).toEqual(["tool-group"]);
    expect((items[0] as { children: ConversationEvent[] }).children).toEqual([]);
  });
});
